"""Authenticated read endpoints not yet generated by the pinned Lighter SDK."""

import os
import re
from decimal import Decimal, InvalidOperation


def _integer(value, name, minimum=0, maximum=2**63 - 1):
    if type(value) is not int or not minimum <= value <= maximum:
        raise ValueError(f"Invalid {name}")
    return value


def _cursor(value):
    if value is not None and not isinstance(value, str):
        raise ValueError("Cursor must be a string")
    return value


class LighterReadApiMixin:
    async def _read_lighter_json(self, path, params):
        # Read-only tokens are instance-scoped; never put credentials in a URL.
        try:
            auth = os.environ.get(f"{self.config_prefix}_READ_ONLY_TOKEN", "").strip()
            if not auth:
                auth = await self._get_auth_token()
            request = self.api_client.param_serialize(
                method="GET", resource_path=path, path_params={},
                query_params=[(key, value) for key, value in params.items() if value is not None],
                header_params={"Accept": "application/json", "authorization": auth},
                body=None, post_params=[], files={}, auth_settings=[], collection_formats={},
            )
            response = await self.api_client.call_api(*request, _request_timeout=15)
            await response.read()
            data = self.api_client.response_deserialize(
                response_data=response, response_types_map={"200": "object"},
            ).data
            if not isinstance(data, dict) or data.get("code") != 200:
                raise ValueError("Unsuccessful API response")
            return data
        except Exception:
            # SDK exceptions may include authenticated request/response details.
            raise RuntimeError(f"{self.exchange_name} read request failed") from None

    async def get_account_order_fills(self, market_id, start_timestamp, end_timestamp,
                                      *, limit=1000, cursor=None):
        """Read one page. Query times are Unix seconds; fill timestamps are milliseconds.

        The limit/cursor page filled orders only; liquidation/settlement rows may
        recur across pages. Amounts and IDs remain strings, without float rounding.
        """
        _integer(market_id, "market_id")
        _integer(start_timestamp, "start_timestamp")
        _integer(end_timestamp, "end_timestamp")
        _integer(limit, "limit", 1, 1000)
        if start_timestamp >= end_timestamp:
            raise ValueError("Start timestamp must precede end timestamp")
        data = await self._read_lighter_json("/api/v1/accountOrderFills", {
            "account_index": self._account_index(), "market_id": market_id,
            "between_timestamps": f"{start_timestamp}-{end_timestamp}",
            "limit": limit, "cursor": _cursor(cursor),
        })
        _integer(data.get("market_id"), "response market_id")
        if data.get("market_id") != market_id or not isinstance(data.get("fills"), list):
            raise ValueError("Invalid account fills response")
        _cursor(data.get("next_cursor"))
        for fill in data["fills"]:
            if (not isinstance(fill, dict) or fill.get("market_id") != market_id
                    or fill.get("type") not in ("order", "deleverage", "market-settlement")
                    or type(fill.get("is_ask")) is not bool):
                raise ValueError("Invalid account fill")
            _integer(fill.get("market_id"), "fill market_id")
            _integer(fill.get("timestamp"), "fill timestamp")
            for name in ("order_id", "trade_id"):
                value = fill.get(name)
                if not isinstance(value, str) or not value.isascii() or not value.isdecimal():
                    raise ValueError("Invalid fill identifier")
            for name in ("base_amount", "quote_amount"):
                try:
                    value = fill.get(name)
                    if not isinstance(value, str) or not Decimal(value).is_finite() or Decimal(value) < 0:
                        raise ValueError("Invalid fill amount")
                except InvalidOperation:
                    raise ValueError("Invalid fill amount") from None
        return data

    async def get_all_account_order_fills(self, market_id, start_timestamp, end_timestamp,
                                          *, limit=1000, max_pages=100):
        """Collect a bounded history, rejecting loops/errors instead of partial success."""
        _integer(max_pages, "max_pages", 1, 10000)
        cursor, seen_cursors, fills = None, set(), {}
        for _ in range(max_pages):
            page = await self.get_account_order_fills(
                market_id, start_timestamp, end_timestamp, limit=limit, cursor=cursor,
            )
            for fill in page["fills"]:
                identifier = fill["order_id"] if fill["type"] == "order" else fill["trade_id"]
                key = (market_id, fill["type"], identifier)
                # Keep the newest version if an order's aggregate changes while paging.
                if key not in fills or fill["timestamp"] > fills[key]["timestamp"]:
                    fills[key] = fill
            cursor = page.get("next_cursor")
            if not cursor:
                return {"code": 200, "market_id": market_id, "next_cursor": None,
                        "fills": sorted(fills.values(), key=lambda row: row["timestamp"], reverse=True)}
            if cursor in seen_cursors:
                raise ValueError("Repeated account fills cursor")
            seen_cursors.add(cursor)
        raise ValueError("Account fills pagination exceeded max_pages")

    async def get_user_referrals(self, l1_address, *, cursor=None, limit=100):
        """Preserve l1_eligible independently of used_code/used_code_eligible."""
        if not isinstance(l1_address, str) or not re.fullmatch(r"0x[0-9a-fA-F]{40}", l1_address):
            raise ValueError("Invalid L1 address")
        _integer(limit, "limit", 1, 300)
        data = await self._read_lighter_json("/api/v1/referral/userReferrals", {
            "l1_address": l1_address, "cursor": _cursor(cursor), "limit": limit,
        })
        if "l1_eligible" in data and type(data["l1_eligible"]) is not bool:
            raise ValueError("Invalid referral eligibility")
        return data

    async def get_withdrawal_history(self, *, cursor=None, status="all"):
        """Preserve claim fields verbatim; a claim amount is NOT a per-withdrawal amount."""
        if status not in ("all", "pending", "claimable"):
            raise ValueError("Invalid withdrawal filter")
        data = await self._read_lighter_json("/api/v1/withdraw/history", {
            "account_index": self._account_index(), "cursor": _cursor(cursor), "filter": status,
        })
        if not isinstance(data.get("withdraws"), list):
            raise ValueError("Invalid withdrawal history")
        return data
